(function(){"use strict";function r(o){const s=new Uint8Array(o);let n="";for(let t=0;t<s.length;t++)n+=s[t].toString(16).padStart(2,"0");return n}self.onmessage=async o=>{const{sal:s,dificuldade:n,desafio:t}=o.data||{},a=new TextEncoder;try{for(let e=0;e<=n;e++){const c=await crypto.subtle.digest("SHA-256",a.encode(s+e));if(r(c)===t){self.postMessage({numero:e});return}}self.postMessage({numero:null})}catch(e){self.postMessage({numero:null,erro:String(e)})}}})();
